import React from 'react';
import { Card, Progress, Space, Typography, Tag, Divider } from 'antd';
import { CheckCircleOutlined, ClockCircleOutlined } from '@ant-design/icons';

const { Text, Title } = Typography;

interface NestedProgressTrackerProps {
    currentRowIndex: number;
    totalRows: number;
    currentStepIndex: number;
    totalSteps: number;
    currentStepData: {
        startRowIndex: number;
        endRowIndex: number;
        rowsInStep: number;
        text: string;
        shapingDetails?: string;
    } | null;
    completedRows: number[];
}

/**
 * NestedProgressTracker - Shows nested progress tracking for garment → step → row
 * 
 * Displays:
 * - Overall garment progress (all rows)
 * - Current step progress (rows within step)
 * - Current row information with shaping details
 */
const NestedProgressTracker: React.FC<NestedProgressTrackerProps> = ({
    currentRowIndex,
    totalRows,
    currentStepIndex,
    totalSteps,
    currentStepData,
    completedRows
}) => {
    // Calculate overall progress
    const overallProgress = Math.round((completedRows.length / totalRows) * 100);
    
    // Calculate step progress
    const stepProgress = currentStepData ? 
        Math.round(((currentRowIndex - currentStepData.startRowIndex + 1) / currentStepData.rowsInStep) * 100) : 0;
    
    // Current row within step
    const rowInStep = currentStepData ? 
        currentRowIndex - currentStepData.startRowIndex + 1 : 0;
    
    // Check if current row requires shaping
    const requiresShaping = currentStepData?.shapingDetails;
    
    return (
        <Card 
            size="small" 
            title={
                <Space>
                    <ClockCircleOutlined style={{ color: '#1890ff' }} />
                    <Text strong>Knitting Progress</Text>
                </Space>
            }
        >
            <Space direction="vertical" style={{ width: '100%' }} size="middle">
                {/* Overall Garment Progress */}
                <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                        <Text strong style={{ fontSize: '14px' }}>Overall Garment</Text>
                        <Text type="secondary" style={{ fontSize: '12px' }}>
                            {completedRows.length} / {totalRows} rows
                        </Text>
                    </div>
                    <Progress 
                        percent={overallProgress} 
                        strokeColor={{
                            '0%': '#108ee9',
                            '100%': '#87d068',
                        }}
                        size="small"
                    />
                </div>

                <Divider style={{ margin: '8px 0' }} />

                {/* Current Step Progress */}
                {currentStepData && (
                    <div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                            <Text strong style={{ fontSize: '13px' }}>
                                Step {currentStepIndex + 1} of {totalSteps}
                            </Text>
                            <Tag color="blue" style={{ margin: 0 }}>
                                In Progress
                            </Tag>
                        </div>
                        <div style={{ marginBottom: 8 }}>
                            <Text type="secondary" style={{ fontSize: '11px', display: 'block' }}>
                                Rows {currentStepData.startRowIndex + 1}-{currentStepData.endRowIndex + 1} 
                                ({currentStepData.rowsInStep} rows)
                            </Text>
                        </div>
                        <Progress 
                            percent={stepProgress} 
                            strokeColor="#1890ff"
                            size="small"
                            format={() => `${rowInStep}/${currentStepData.rowsInStep}`}
                        />
                        <div style={{ 
                            marginTop: 8, 
                            padding: 8, 
                            background: '#f0f8ff', 
                            borderRadius: 4,
                            border: '1px solid #d6e4ff'
                        }}>
                            <Text style={{ fontSize: '12px' }}>
                                {currentStepData.text}
                            </Text>
                        </div>
                    </div>
                )}

                <Divider style={{ margin: '8px 0' }} />

                {/* Current Row Details */}
                <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                        <Text strong style={{ fontSize: '13px' }}>
                            Current Row: {currentRowIndex + 1}
                        </Text>
                        {completedRows.includes(currentRowIndex) ? (
                            <Tag color="success" icon={<CheckCircleOutlined />}>
                                Complete
                            </Tag>
                        ) : (
                            <Tag color="processing" icon={<ClockCircleOutlined />}>
                                Knitting
                            </Tag>
                        )}
                    </div>
                    
                    {/* Show shaping alert if this row requires shaping */}
                    {requiresShaping && (
                        <div style={{
                            padding: 10,
                            background: requiresShaping.toLowerCase().includes('hold') || 
                                       requiresShaping.toLowerCase().includes('turn') || 
                                       requiresShaping.toLowerCase().includes('short row') 
                                ? '#e6f7ff' : '#fff7e6',
                            border: requiresShaping.toLowerCase().includes('hold') || 
                                   requiresShaping.toLowerCase().includes('turn') || 
                                   requiresShaping.toLowerCase().includes('short row')
                                ? '1px solid #91d5ff' : '1px solid #ffd591',
                            borderRadius: 4,
                            marginTop: 8
                        }}>
                            <Space direction="vertical" size={2}>
                                <Text strong style={{ 
                                    fontSize: '12px', 
                                    color: requiresShaping.toLowerCase().includes('hold') || 
                                          requiresShaping.toLowerCase().includes('turn') || 
                                          requiresShaping.toLowerCase().includes('short row')
                                        ? '#096dd9' : '#d46b08'
                                }}>
                                    {requiresShaping.toLowerCase().includes('hold') || 
                                     requiresShaping.toLowerCase().includes('turn') || 
                                     requiresShaping.toLowerCase().includes('short row')
                                        ? 'ℹ️ Short Row' : '⚠️ Shaping Required on This Row'}
                                </Text>
                                <Text style={{ 
                                    fontSize: '11px', 
                                    color: requiresShaping.toLowerCase().includes('hold') || 
                                          requiresShaping.toLowerCase().includes('turn') || 
                                          requiresShaping.toLowerCase().includes('short row')
                                        ? '#003a8c' : '#874d00'
                                }}>
                                    {requiresShaping}
                                </Text>
                            </Space>
                        </div>
                    )}
                    
                    {/* Progress within step */}
                    {currentStepData && (
                        <div style={{ marginTop: 8 }}>
                            <Text type="secondary" style={{ fontSize: '11px' }}>
                                Row {rowInStep} of {currentStepData.rowsInStep} in this step
                            </Text>
                        </div>
                    )}
                </div>
            </Space>
        </Card>
    );
};

export default NestedProgressTracker;
