import React, { useState, useEffect, useRef } from 'react';
import { Card, Button, Row, Col, Space, Typography, Progress, Tag, Divider, Collapse, Select } from 'antd';
import { LeftOutlined, RightOutlined, CheckOutlined } from '@ant-design/icons';
import RowByRowInstructions from './RowByRowInstructions';
import NestedProgressTracker from './NestedProgressTracker';
import { ColorworkStitchPlanService } from '../models/ColorworkStitchPlanService';
import { UnifiedPanelDiagram } from './UnifiedPanelDiagram';
import { calculateStepFromRow, getProgressMapping } from '../utils/knittingProgressUtils';

const { Title, Text } = Typography;
const { Panel } = Collapse;

/**
 * InteractiveKnittingView - Enhanced knitting interface with row tracking and colorwork guidance
 * Two-column layout: Left = Controls & Preview, Right = Scrollable Steps
 */
const InteractiveKnittingView = ({
    combinedPattern,
    instructions = [],
    knittingProgress,
    onRowComplete,
    onBackToSettings
}: {
    combinedPattern: any;
    instructions?: any[];
    knittingProgress: any;
    onRowComplete: (rowIndex: number) => void;
    onBackToSettings: () => void;
}) => {
    const [enhancedStitchPlan, setEnhancedStitchPlan] = useState<any>(null);
    const [currentRowInstructions, setCurrentRowInstructions] = useState<any>(null);
    const [knittingMode, setKnittingMode] = useState<'hand' | 'machine'>('machine'); // Default to machine knitting
    const [generatedInstructions, setGeneratedInstructions] = useState<any[]>([]);
    const stepsScrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (combinedPattern) {
            console.log('[InteractiveKnittingView] combinedPattern:', combinedPattern);
            console.log('[InteractiveKnittingView] colorworkLayers:', combinedPattern.colorworkLayers);
            console.log('[InteractiveKnittingView] panel:', combinedPattern.panel);
            
            // Create enhanced stitch plan with colorwork using the combined pattern's stitchPlan
            // The stitchPlan should already be enhanced with colorwork data from PanelColorworkComposer
            if (combinedPattern.stitchPlan && combinedPattern.stitchPlan.hasColorwork()) {
                setEnhancedStitchPlan(combinedPattern.stitchPlan);
            } else {
                // Fallback: create enhanced stitch plan with colorwork
                const service: any = new ColorworkStitchPlanService();
                const panel = combinedPattern.panel;
                const colorworkPattern = combinedPattern.colorworkPattern;
                
                try {
                    const enhanced = service.createColorworkStitchPlan(panel, colorworkPattern);
                    setEnhancedStitchPlan(enhanced);
                } catch (error: unknown) {
                    console.error('Error creating enhanced stitch plan:', error);
                }
            }
        }
    }, [combinedPattern]);

    // Regenerate instructions when knitting mode or stitch plan changes
    useEffect(() => {
        if (enhancedStitchPlan) {
            console.log('[InteractiveKnittingView] Generating instructions for mode:', knittingMode);
            
            // Import actualizers dynamically
            import('../models/HandKnittingActualizer').then(({ HandKnittingActualizer }) => {
                import('../models/MachineKnittingActualizer').then(({ MachineKnittingActualizer }) => {
                    const actualizer = knittingMode === 'machine' 
                        ? new MachineKnittingActualizer()
                        : new HandKnittingActualizer();
                    
                    const instructions = actualizer.actualize(enhancedStitchPlan.rows, 0);
                    console.log('[InteractiveKnittingView] Generated instructions:', instructions);
                    setGeneratedInstructions(instructions);
                });
            });
        }
    }, [enhancedStitchPlan, knittingMode]);

    useEffect(() => {
        if (enhancedStitchPlan && enhancedStitchPlan.rows[knittingProgress.currentRowIndex]) {
            const currentRow = enhancedStitchPlan.rows[knittingProgress.currentRowIndex];
            setCurrentRowInstructions(currentRow);
        }
    }, [enhancedStitchPlan, knittingProgress.currentRowIndex]);

    // Auto-scroll to active step
    useEffect(() => {
        if (stepsScrollRef.current && generatedInstructions.length > 0) {
            const currentStepIndex = calculateStepFromRow(knittingProgress.currentRowIndex, generatedInstructions);
            
            // Find the active step card element and scroll the container to it
            const stepCards = stepsScrollRef.current.querySelectorAll('.step-card');
            if (stepCards[currentStepIndex]) {
                const stepCard = stepCards[currentStepIndex] as HTMLElement;
                const container = stepsScrollRef.current;
                
                // Calculate the position to scroll to (center the card in the container)
                const cardTop = stepCard.offsetTop;
                const cardHeight = stepCard.offsetHeight;
                const containerHeight = container.clientHeight;
                const scrollTo = cardTop - (containerHeight / 2) + (cardHeight / 2);
                
                // Scroll the container, not the whole page
                container.scrollTo({ 
                    top: scrollTo,
                    behavior: 'smooth'
                });
            }
        }
    }, [knittingProgress.currentRowIndex, generatedInstructions]);

    const handlePreviousRow = () => {
        if (knittingProgress.currentRowIndex > 0) {
            // Move back to previous row (but don't mark it incomplete)
            // This is just for navigation
        }
    };

    const handleNextRow = () => {
        if (knittingProgress.currentRowIndex < instructions.length - 1) {
            onRowComplete(knittingProgress.currentRowIndex);
        }
    };

    const progressPercent = Math.round((knittingProgress.completedRows.length / instructions.length) * 100);

    return (
        <div className="interactive-knitting-view" style={{ background: '#f5f5f5', minHeight: '100vh' }}>
            <Row gutter={24} style={{ height: '100vh', margin: 0 }}>
                {/* LEFT COLUMN: Controls, Progress, and Preview */}
                <Col xs={24} lg={10} style={{ 
                    padding: '24px',
                    height: '100vh',
                    overflowY: 'auto'
                }}>
                    <Space direction="vertical" style={{ width: '100%' }} size="large">
                        {/* Knitting Mode Selector */}
                        <Card size="small">
                            <Space>
                                <Text strong>Knitting Mode:</Text>
                                <Select
                                    value={knittingMode}
                                    onChange={setKnittingMode}
                                    style={{ width: 200 }}
                                    options={[
                                        { value: 'hand', label: 'Hand Knitting' },
                                        { value: 'machine', label: 'Machine Knitting' }
                                    ]}
                                />
                            </Space>
                        </Card>

                        {/* Progress Overview */}
                        {enhancedStitchPlan && generatedInstructions.length > 0 && (() => {
                            const currentStepIndex = calculateStepFromRow(knittingProgress.currentRowIndex, generatedInstructions);
                            const currentStepData = currentStepIndex < generatedInstructions.length 
                                ? generatedInstructions[currentStepIndex]?.stepData 
                                : null;

                            return (
                                <NestedProgressTracker
                                    currentRowIndex={knittingProgress.currentRowIndex}
                                    totalRows={enhancedStitchPlan.rows.length}
                                    currentStepIndex={currentStepIndex}
                                    totalSteps={generatedInstructions.length}
                                    currentStepData={currentStepData}
                                    completedRows={knittingProgress.completedRows}
                                />
                            );
                        })()}

                        {/* Current Row Controls */}
                        <Card 
                            title={`Row ${knittingProgress.currentRowIndex + 1}`}
                            extra={
                                <Tag color={knittingProgress.completedRows.includes(knittingProgress.currentRowIndex) ? 'green' : 'blue'}>
                                    {knittingProgress.completedRows.includes(knittingProgress.currentRowIndex) ? 'Complete' : 'In Progress'}
                                </Tag>
                            }
                        >
                            {currentRowInstructions && (
                                <Space direction="vertical" style={{ width: '100%' }} size="middle">
                                    {/* Shaping Information */}
                                    <div>
                                        <Text strong>Stitches:</Text>
                                        <div style={{ marginTop: 8, padding: 12, background: '#f0f8ff', borderRadius: 6 }}>
                                            <Text>
                                                {currentRowInstructions.leftStitchesInWork + currentRowInstructions.rightStitchesInWork} total
                                                <Text type="secondary" style={{ marginLeft: 8 }}>
                                                    ({currentRowInstructions.leftStitchesInWork}L + {currentRowInstructions.rightStitchesInWork}R)
                                                </Text>
                                            </Text>
                                        </div>
                                    </div>

                                    {/* Colorwork Pattern */}
                                    {currentRowInstructions.getColorworkInstructions && currentRowInstructions.getColorworkInstructions() && (
                                        <div>
                                            <Text strong>Colors:</Text>
                                            <div style={{ marginTop: 8 }}>
                                                <Space wrap size="small">
                                                    {currentRowInstructions.getColorworkInstructions().map((segment: any, index: number) => (
                                                        <Tag 
                                                            key={index}
                                                            style={{ 
                                                                backgroundColor: segment.colorHex,
                                                                color: getContrastColor(segment.colorHex),
                                                                fontWeight: 'bold',
                                                                border: '1px solid #d9d9d9'
                                                            }}
                                                        >
                                                            {segment.stitchCount} {segment.colorLabel}
                                                        </Tag>
                                                    ))}
                                                </Space>
                                                
                                                {/* Visual color bar */}
                                                <ColorworkRowBar 
                                                    colorworkInstructions={currentRowInstructions.getColorworkInstructions()}
                                                    totalStitches={currentRowInstructions.leftStitchesInWork + currentRowInstructions.rightStitchesInWork}
                                                />
                                            </div>
                                        </div>
                                    )}

                                    <Divider style={{ margin: '12px 0' }} />

                                    {/* Navigation Controls */}
                                    <Row gutter={8}>
                                        <Col span={8}>
                                            <Button 
                                                icon={<LeftOutlined />}
                                                onClick={handlePreviousRow}
                                                disabled={knittingProgress.currentRowIndex === 0}
                                                block
                                            >
                                                Prev
                                            </Button>
                                        </Col>
                                        <Col span={8}>
                                            <Button 
                                                type="primary"
                                                icon={<CheckOutlined />}
                                                onClick={handleNextRow}
                                                disabled={knittingProgress.currentRowIndex >= instructions.length - 1}
                                                block
                                            >
                                                Complete
                                            </Button>
                                        </Col>
                                        <Col span={8}>
                                            <Button 
                                                icon={<RightOutlined />}
                                                onClick={handleNextRow}
                                                disabled={knittingProgress.currentRowIndex >= instructions.length - 1}
                                                block
                                            >
                                                Next
                                            </Button>
                                        </Col>
                                    </Row>
                                </Space>
                            )}
                        </Card>

                        {/* Garment Preview with Current Row Highlighted */}
                        <Card title="Garment Preview">
                            <div style={{ 
                                background: 'white', 
                                padding: '20px', 
                                borderRadius: '8px',
                                textAlign: 'center'
                            }}>
                                {combinedPattern?.panel?.shape && combinedPattern?.panel?.gauge && (
                                    <UnifiedPanelDiagram
                                        shape={combinedPattern.panel.shape}
                                        patternLayers={
                                            combinedPattern.colorworkLayers && 
                                            Array.isArray(combinedPattern.colorworkLayers) && 
                                            combinedPattern.colorworkLayers.length > 0 
                                                ? combinedPattern.colorworkLayers.filter((layer: any) => 
                                                    layer && (layer.pattern || layer.grid)
                                                  )
                                                : []
                                        }
                                        gauge={combinedPattern.panel.gauge}
                                        size={300}
                                        showPatterns={
                                            combinedPattern.colorworkLayers && 
                                            combinedPattern.colorworkLayers.length > 0
                                        }
                                        showProgress={true}
                                        highlightedRow={knittingProgress.currentRowIndex}
                                        completedRows={knittingProgress.completedRows}
                                        showLabels={false}
                                        showShortRows={true}
                                        stitchPlan={combinedPattern.stitchPlan}
                                    />
                                )}
                            </div>
                        </Card>
                    </Space>
                </Col>

                {/* RIGHT COLUMN: Scrollable Step-by-Step Instructions */}
                <Col xs={24} lg={14} style={{ 
                    background: 'white',
                    borderLeft: '1px solid #e8e8e8',
                    height: '100vh',
                    overflowY: 'auto',
                    padding: '24px'
                }}>
                    <div style={{ marginBottom: 16 }}>
                        <Title level={4} style={{ margin: 0 }}>Step-by-Step Instructions</Title>
                        <Text type="secondary">Scroll through all steps. Active step is highlighted.</Text>
                    </div>

                    {generatedInstructions.length > 0 && (() => {
                        const currentStepIndex = calculateStepFromRow(knittingProgress.currentRowIndex, generatedInstructions);

                        return (
                            <div ref={stepsScrollRef}>
                                {generatedInstructions.map((instruction: any, stepIndex: number) => {
                                    const stepData = instruction.stepData || null;
                                    const instrText = instruction.text || String(instruction);
                                    const rowInstructions = instruction.rows || [];
                                    
                                    const isCurrentStep = stepIndex === currentStepIndex;
                                    const isCompleted = stepIndex < currentStepIndex;
                                    
                                    const stepStartRow = stepData?.startRowIndex ?? stepIndex;
                                    const stepEndRow = stepData?.endRowIndex ?? stepIndex;
                                    const isWithinThisStep = knittingProgress.currentRowIndex >= stepStartRow && 
                                                            knittingProgress.currentRowIndex <= stepEndRow;
                                    const shouldHighlight = isCurrentStep || isWithinThisStep;
                                    
                                    const rowsInStep = stepData?.rowsInStep ?? 1;
                                    const completedRowsInStep = knittingProgress.completedRows.filter(
                                        (rowIdx: number) => rowIdx >= stepStartRow && rowIdx <= stepEndRow
                                    ).length;
                                    const stepProgressPercent = Math.round((completedRowsInStep / rowsInStep) * 100);
                                    
                                    // Generate better step title
                                    const displayLabel = generateStepTitle(stepIndex, instrText, stepData);
                                    
                                    // Get current row instruction for active steps
                                    const currentRowInStep = isCurrentStep && rowInstructions.length > 0 
                                        ? rowInstructions[knittingProgress.currentRowIndex - stepStartRow]
                                        : null;
                                    
                                    return (
                                        <Card 
                                            key={stepIndex}
                                            className="step-card"
                                            size="small"
                                            style={{
                                                marginBottom: 16,
                                                backgroundColor: shouldHighlight ? '#e6f7ff' : isCompleted ? '#f6ffed' : 'white',
                                                border: shouldHighlight ? '2px solid #1890ff' : '1px solid #d9d9d9',
                                                boxShadow: shouldHighlight ? '0 2px 8px rgba(24, 144, 255, 0.2)' : 'none'
                                            }}
                                        >
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                                                <Text strong>{displayLabel}</Text>
                                                {isCompleted ? (
                                                    <Tag color="success">Completed</Tag>
                                                ) : isCurrentStep ? (
                                                    <Tag color="processing">In Progress</Tag>
                                                ) : (
                                                    <Tag>Upcoming</Tag>
                                                )}
                                            </div>
                                            
                                            {/* Progress bar with current row shaping for active steps */}
                                            {(isCurrentStep || isCompleted) && stepData && (
                                                <div>
                                                    <Progress 
                                                        percent={stepProgressPercent}
                                                        size="small"
                                                        strokeColor={isCompleted ? '#52c41a' : '#1890ff'}
                                                        format={() => `${completedRowsInStep}/${rowsInStep} rows`}
                                                        style={{ marginBottom: currentRowInStep ? 8 : 12 }}
                                                    />
                                                    {currentRowInStep && (
                                                        <div style={{
                                                            padding: '8px 12px',
                                                            background: '#f0f8ff',
                                                            borderRadius: '4px',
                                                            marginBottom: 12,
                                                            borderLeft: '3px solid #1890ff'
                                                        }}>
                                                            <Text strong style={{ fontSize: '12px', color: '#1890ff' }}>
                                                                Current Row:
                                                            </Text>
                                                            <br />
                                                            <Text style={{ fontSize: '13px' }}>
                                                                {currentRowInStep}
                                                            </Text>
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                            
                                            <Text type="secondary" style={{ display: 'block', marginBottom: rowInstructions.length > 0 ? 12 : 0, fontSize: '13px' }}>
                                                {instrText}
                                            </Text>
                                            
                                            {rowInstructions.length > 0 && (
                                                <Collapse 
                                                    ghost 
                                                    size="small"
                                                    defaultActiveKey={isCurrentStep ? ['rows'] : []}
                                                >
                                                    <Panel 
                                                        header={`Row Details (${rowInstructions.length} rows)`} 
                                                        key="rows"
                                                    >
                                                        <div style={{ 
                                                            maxHeight: '300px', 
                                                            overflowY: 'auto',
                                                            paddingLeft: '8px'
                                                        }}>
                                                            {rowInstructions.map((rowInstr: string, rowIdx: number) => {
                                                                const rowIndex = stepStartRow + rowIdx;
                                                                const isRowCompleted = knittingProgress.completedRows.includes(rowIndex);
                                                                const isCurrentRow = knittingProgress.currentRowIndex === rowIndex;
                                                                
                                                                return (
                                                                    <div 
                                                                        key={rowIdx}
                                                                        style={{
                                                                            padding: '6px 8px',
                                                                            fontSize: '13px',
                                                                            color: isRowCompleted ? '#52c41a' : isCurrentRow ? '#1890ff' : 'inherit',
                                                                            fontWeight: isCurrentRow ? 'bold' : 'normal',
                                                                            backgroundColor: isCurrentRow ? '#e6f7ff' : 'transparent',
                                                                            borderRadius: '4px',
                                                                            marginBottom: '4px'
                                                                        }}
                                                                    >
                                                                        {isRowCompleted && '✓ '}
                                                                        {isCurrentRow && '→ '}
                                                                        {rowInstr}
                                                                    </div>
                                                                );
                                                            })}
                                                        </div>
                                                    </Panel>
                                                </Collapse>
                                            )}
                                        </Card>
                                    );
                                })}
                            </div>
                        );
                    })()}
                </Col>
            </Row>
        </div>
    );
};

/**
 * ColorworkRowBar - Visual representation of a single row's colorwork pattern
 */
const ColorworkRowBar = ({ colorworkInstructions, totalStitches }: { colorworkInstructions: any[], totalStitches: number }) => {
    if (!colorworkInstructions || colorworkInstructions.length === 0) {
        return null;
    }

    const stitchWidth = Math.max(2, Math.min(8, 300 / totalStitches));
    const barWidth = totalStitches * stitchWidth;
    const barHeight = 20;

    let currentPosition = 0;
    const segments = colorworkInstructions.map((segment: any, index: number) => {
        const segmentWidth = segment.stitchCount * stitchWidth;
        const rect = (
            <rect
                key={index}
                x={currentPosition}
                y={0}
                width={segmentWidth}
                height={barHeight}
                fill={segment.colorHex}
                stroke="#666"
                strokeWidth="0.5"
            />
        );
        currentPosition += segmentWidth;
        return rect;
    });

    return (
        <div style={{ marginTop: 8 }}>
            <svg 
                width={barWidth} 
                height={barHeight}
                style={{ 
                    border: '1px solid #ddd', 
                    borderRadius: '4px',
                    display: 'block'
                }}
            >
                {segments}
            </svg>
        </div>
    );
};

/**
 * Calculate contrast color for text visibility
 */
const getContrastColor = (hexColor: string) => {
    // Remove # if present
    const hex = hexColor.replace('#', '');
    
    // Convert to RGB
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);
    
    // Calculate luminance
    const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    
    return luminance > 0.5 ? '#000000' : '#ffffff';
};

/**
 * Generate a concise, descriptive step title from instruction text
 */
const generateStepTitle = (stepIndex: number, instrText: string, stepData: any): string => {
    // Handle cast-on
    if (instrText.includes('CO ') && instrText.includes('cast-on')) {
        const stitches = instrText.match(/CO (\d+)/)?.[1] || '?';
        return `Step ${stepIndex + 1}: Cast On ${stitches} stitches`;
    }
    
    // Handle bind-off
    if (instrText.includes('BO ') && instrText.includes('bind-off')) {
        const stitches = instrText.match(/BO all (\d+)/)?.[1] || '?';
        return `Step ${stepIndex + 1}: Bind Off ${stitches} stitches`;
    }
    
    // Check for short row sections - now split into decrease and increase phases
    if (instrText.includes('SHORT ROW SECTION')) {
        const rowCount = stepData?.rowsInStep || '?';
        
        // Extract the section label (left/right)
        const labelMatch = instrText.match(/SHORT ROW SECTION \(([^)]+)\)/);
        const label = labelMatch ? labelMatch[1] : '';
        
        // Check for explicit phase markers
        if (instrText.includes('DECREASE PHASE')) {
            return `Step ${stepIndex + 1}: ${label} short rows - decreases (${rowCount} rows)`;
        } else if (instrText.includes('INCREASE PHASE')) {
            return `Step ${stepIndex + 1}: ${label} short rows - increases (${rowCount} rows)`;
        }
        
        // Fallback: check content (hand vs machine terminology)
        if (instrText.includes('PICK UP:') || instrText.includes('RETURN:') || instrText.includes('increasing')) {
            return `Step ${stepIndex + 1}: ${label} short rows - increases (${rowCount} rows)`;
        } else if (instrText.includes('HOLD:') || instrText.includes('TRANSFER:') || instrText.includes('decreasing')) {
            return `Step ${stepIndex + 1}: ${label} short rows - decreases (${rowCount} rows)`;
        } else {
            return `Step ${stepIndex + 1}: ${label} short rows (${rowCount} rows)`;
        }
    }
    
    // Legacy short row handling - for decrease/increase phases
    if (instrText.includes('SHORT ROW DECREASE PHASE')) {
        const rowCount = stepData?.rowsInStep || '?';
        return `Step ${stepIndex + 1}: Short Row Decreases (${rowCount} rows)`;
    }
    
    if (instrText.includes('SHORT ROW INCREASE PHASE')) {
        const rowCount = stepData?.rowsInStep || '?';
        return `Step ${stepIndex + 1}: Short Row Increases (${rowCount} rows)`;
    }
    
    if (instrText.includes('HOLD:') || instrText.includes('PICK UP:')) {
        // Single section short rows
        const rowCount = stepData?.rowsInStep || '?';
        if (instrText.includes('PICK UP:')) {
            return `Step ${stepIndex + 1}: Short Row Increases (${rowCount} rows)`;
        } else {
            return `Step ${stepIndex + 1}: Short Row Decreases (${rowCount} rows)`;
        }
    }
    
    // Legacy short row handling (fallback)
    if (instrText.includes('short row') || instrText.includes('Short row') || 
        instrText.includes('Wrap') || instrText.match(/section:/i)) {
        
        // Try to extract the starting row counter
        const rcMatch = instrText.match(/\(RC=(\d+)\)/);
        if (rcMatch) {
            const startRow = rcMatch[1];
            return `Step ${stepIndex + 1}: Short rows starting at row ${startRow}`;
        }
        
        // Fallback: extract row count from stepData
        const rowCount = stepData?.rowsInStep || '?';
        return `Step ${stepIndex + 1}: Short rows (${rowCount} rows total)`;
    }
    
    // Extract row count and shaping info for regular rows
    // Support both hand knitting ("Knit X rows") and machine knitting ("Machine-knit across X needles for Y rows")
    const rowMatch = instrText.match(/Knit (\d+) rows?/) || instrText.match(/for (\d+) rows/);
    const rowCount = rowMatch ? rowMatch[1] : stepData?.rowsInStep || '?';
    
    // Check for machine knitting rectangular sections
    if (instrText.includes('Machine-knit across') || instrText.includes('Pass yarn carriage')) {
        const needles = instrText.match(/across (\d+) needles/)?.[1] || '?';
        return `Step ${stepIndex + 1}: Knit ${rowCount} rows (${needles} needles)`;
    }
    
    // Check for shaping instructions
    if (instrText.includes('Inc') || instrText.includes('Dec')) {
        // Extract shaping details
        const hasInc = instrText.includes('Inc') || instrText.includes('increasing');
        const hasDec = instrText.includes('Dec') || instrText.includes('decreasing');
        
        // Try to extract stitch count changes
        const fromToMatch = instrText.match(/from (\d+) to (\d+)/);
        if (fromToMatch) {
            const from = fromToMatch[1];
            const to = fromToMatch[2];
            const diff = parseInt(to) - parseInt(from);
            
            if (diff > 0) {
                return `Step ${stepIndex + 1}: Knit ${rowCount} rows, increasing ${diff} stitches`;
            } else if (diff < 0) {
                return `Step ${stepIndex + 1}: Knit ${rowCount} rows, decreasing ${-diff} stitches`;
            }
        }
        
        // General shaping description
        if (hasInc && hasDec) {
            return `Step ${stepIndex + 1}: Knit ${rowCount} rows with shaping`;
        } else if (hasInc) {
            return `Step ${stepIndex + 1}: Knit ${rowCount} rows, increasing`;
        } else {
            return `Step ${stepIndex + 1}: Knit ${rowCount} rows, decreasing`;
        }
    }
    
    // No shaping - rectangular section
    return `Step ${stepIndex + 1}: Knit ${rowCount} rows without shaping`;
};

export default InteractiveKnittingView;
